1	import WebSocket from 'ws';
2	
3	// --- Persistent WebSocket connection per game room ---
4	
5	class GameConnection {
6	  constructor(wsUrl, roomId, token) {
7	    this.wsUrl = wsUrl;
8	    this.roomId = roomId;
9	    this.token = token;
10	    this.state = 'connecting'; // connecting | connected | reconnecting | closed
11	    this.eventBuffer = [];
12	    this.waiters = [];
13	    this.retryCount = 0;
14	    this.maxRetries = 5;
15	    this.ws = null;
16	    this._readyResolve = null;
17	    this.readyPromise = new Promise((resolve) => { this._readyResolve = resolve; });
18	    this._connect();
19	  }
20	
21	  _connect() {
22	    const url = `${this.wsUrl}/api/rooms/${this.roomId}/ws?token=${this.token}`;
23	    this.ws = new WebSocket(url);
24	
25	    this.ws.on('open', () => {
26	      this.state = 'connected';
27	      this.retryCount = 0;
28	      if (this._readyResolve) {
29	        this._readyResolve();
30	        this._readyResolve = null;
31	      }
32	    });
33	
34	    this.ws.on('message', (data) => {
35	      try {
36	        const msg = JSON.parse(data.toString());
37	        const idx = this.waiters.findIndex((w) => w.eventNames.includes(msg.event));
38	        if (idx >= 0) {
39	          const waiter = this.waiters.splice(idx, 1)[0];
40	          clearTimeout(waiter.timer);
41	          waiter.resolve(msg);
42	        } else {
43	          this.eventBuffer.push(msg);
44	          if (this.eventBuffer.length > 100) this.eventBuffer.shift();
45	        }
46	      } catch {
47	        // ignore malformed messages
48	      }
49	    });
50	
51	    this.ws.on('error', () => {
52	      // close event always follows — reconnection handled there
53	    });
54	
55	    this.ws.on('close', () => {
56	      if (this.state === 'closed') return;
57	      this.state = 'reconnecting';
58	      this._reconnect();
59	    });
60	  }
61	
62	  _reconnect() {
63	    if (this.state === 'closed') return;
64	    if (this.retryCount >= this.maxRetries) {
65	      this._fail(new Error('Max reconnection attempts exceeded'));
66	      return;
67	    }
68	    const delay = Math.min(1000 * 2 ** this.retryCount, 30000);
69	    this.retryCount++;
70	    this.readyPromise = new Promise((resolve) => { this._readyResolve = resolve; });
71	    setTimeout(() => {
72	      if (this.state === 'closed') return;
73	      this._connect();
74	    }, delay);
75	  }
76	
77	  _fail(err) {
