// Fresh DB
const db = createDb();
const { createAuthRouter } = require('./routes/auth');
const router = createAuthRouter(db, { passkeyServerUrl: 'http://localhost:3000' });

function hashToken(t) {
  return crypto.createHash('sha256').update(t).digest('hex');
}

// 1. Test signup prepared statement
const token = uuidv4();
const tokenHash = hashToken(token);
const ttl = '+30 days';

const insertUser = db.prepare(
  "INSERT INTO users (username, token_hash, token_expires_at) VALUES (?, ?, datetime('now', ?))"
);
insertUser.run('test-bot', tokenHash, ttl);
console.log('1. Signup OK');

// 2. Lookup by hash
const findByHash = db.prepare(
  'SELECT id, username, token_hash, token_expires_at FROM users WHERE token_hash = ?'
);
const user = findByHash.get(tokenHash);
console.log(`2. Auth lookup: user=${user.username}, expires=${user.token_expires_at}`);

// 3. Wrong token
const badUser = findByHash.get(hashToken('wrong'));
console.log(`3. Wrong token: ${badUser ? 'FAIL' : 'OK - rejected'}`);

// 4. Refresh
const newToken = uuidv4();
const newHash = hashToken(newToken);
const updateToken = db.prepare(
  "UPDATE users SET token_hash = ?, token_expires_at = datetime('now', ?) WHERE id = ?"
);
updateToken.run(newHash, ttl, user.id);

const refreshed = findByHash.get(newHash);
const oldGone = findByHash.get(tokenHash);
console.log(`4. Refresh: new=${!!refreshed}, old=${!!oldGone}`);

// 5. Revoke
db.prepare('UPDATE users SET token_hash = NULL, token_expires_at = NULL WHERE id = ?').run(user.id);
const revoked = findByHash.get(newHash);
console.log(`5. Revoke: token works=${!!revoked}`);

// 6. Expiry check
const expiredToken = uuidv4();
const expiredHash = hashToken(expiredToken);
db.prepare(
  "INSERT INTO users (username, token_hash, token_expires_at) VALUES (?, ?, datetime('now', ?))"
).run('expired-bot', expiredHash, '-1 days');
const expiredUser = db.prepare(
  'SELECT id, username, token_expires_at FROM users WHERE token_hash = ?'
).get(expiredHash);
const isExpired = new Date(expiredUser.token_expires_at + 'Z') <= new Date();
console.log(`6. Expiry: expires=${expiredUser.token_expires_at}, isExpired=${isExpired}`);

db.close();
console.log('\nALL TESTS PASSED');

